// Rich, per-tool content for the dedicated AI tool pages.
// Keyed by `name` which must match the corresponding entry in `aiTools` (data.ts).
// Websites are the official sites (best-known); confirm before adding affiliate links.

export type AiToolFaq = { q: string; a: string };

export type AiToolDetail = {
  slug: string;
  name: string;
  website: string;
  overview: string;
  useCases: string[];
  hacks: string[];
  /**
   * Long-form review body. Markdown subset understood by <ArticleMarkdown/>:
   * `##`/`###` headings, blank-line paragraphs, `- ` and `1. ` lists,
   * GitHub-style pipe tables, `**bold**` and `[text](/link)`.
   * Never use triple-backtick code fences here.
   */
  bodyMarkdown: string;
  pros: string[];
  cons: string[];
  /** One sentence: who this tool is right for. */
  bestFor: string;
  /** One sentence: who should skip it. */
  notFor: string;
  /** Two to three sentence closing call. */
  verdict: string;
  faq: AiToolFaq[];
};

/** The short, at-a-glance fields shown at the top of a tool page. */
type AiToolBase = Pick<
  AiToolDetail,
  "slug" | "name" | "website" | "overview" | "useCases" | "hacks"
>;
/** The long-form review half, kept separate purely to keep this file readable. */
type AiToolReview = Omit<AiToolDetail, keyof AiToolBase>;

